def transform(grid):
    R, C = len(grid), len(grid[0])
    seen=set(); blocks=[]
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 0 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<R and 0<=xx<C and grid[yy][xx]!=0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            if r1-r0==2 and c1-c0==2:
                b=[row[c0:c1+1] for row in grid[r0:r1+1]]
                if all(v for row in b for v in row): blocks.append(b)
    for b in blocks:
        if len({v for row in b for v in row}) == 3: return b
    return blocks[0] if blocks else []
